using System;using System.Collections;using System.Reflection;using UnityEngine;
public sealed class PowerTackleTests:MonoBehaviour
{
 public static bool OverrideAxes=true;public static float FanAxis,ZhaoAxis;static bool started;
 public static int SelectedMode;
 public static bool IsTestHuman(Component p){return !((SelectedMode==1&&p.name=="Zhao")||(SelectedMode==2&&p.name=="Fan"));}
 const BindingFlags P=BindingFlags.Instance|BindingFlags.NonPublic;
 Component fan,zhao;Rigidbody2D fb,zb,ball;PlayerSkills fs,zs;Type pt;int failures,checks;
 float groundBaseline,airBaseline,groundSpecial,airSpecial;
 public static void Boot(){if(started)return;started=true;var o=new GameObject("PowerTackleTests");DontDestroyOnLoad(o);o.AddComponent<PowerTackleTests>();}
 void Check(bool ok,string label){checks++;Debug.Log((ok?"TACKLE PASS ":"TACKLE FAIL ")+label);if(!ok)failures++;}
 object Field(PlayerSkills s,string n){return typeof(PlayerSkills).GetField(n,P).GetValue(s);}
 float Fx(){return zs==null?-10:((float[])Field(zs,"effects"))[3];}
 void Move(Component p,Rigidbody2D b,Vector2 pos){p.transform.position+=(Vector3)(pos-b.position);Physics2D.SyncTransforms();}
 float Joints(Component p){float max=0;foreach(HingeJoint2D j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)max=Mathf.Max(max,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return max;}
 IEnumerator Scene(bool skills,int mode=0){SelectedMode=mode;FanAxis=ZhaoAxis=0;PlayerSkills.Enabled=skills;typeof(GameAIMod).GetMethod("StartGame",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{mode});yield return new WaitForSeconds(.15f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=(Rigidbody2D)pt.GetField("rb").GetValue(fan);zb=(Rigidbody2D)pt.GetField("rb").GetValue(zhao);fs=fan.GetComponent<PlayerSkills>();zs=zhao.GetComponent<PlayerSkills>();ball=(FindObjectOfType(Type.GetType("Ball, Assembly-CSharp")) as Component).GetComponent<Rigidbody2D>();ball.position=new Vector2(0,4.3f);ball.gravityScale=0;ball.velocity=Vector2.zero;}
 IEnumerator Contest(bool skills,bool air,bool rear=false){yield return Scene(skills);float y=air?2.2f:fb.position.y;Move(fan,fb,new Vector2(-1.25f,y));Move(zhao,zb,new Vector2(1.25f,y));ball.position=new Vector2(rear?5:0,40);if(air){fan.GetComponent<Animator>().SetTrigger("Jump");zhao.GetComponent<Animator>().SetTrigger("Jump");}foreach(var b in fan.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(air?3f:0,air?2f:0);foreach(var b in zhao.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(air?-3f:0,air?2f:0);FanAxis=1;ZhaoAxis=-1;
  float maxTilt=0,maxError=0,first=-10,firstGain=0,firstMass=0,lastFx=-10;int activations=0;float mass=zb.mass;bool airborneActivation=false,captured=false;
  for(int i=0;i<110;i++){yield return new WaitForFixedUpdate();float err=Mathf.Max(Joints(fan),Joints(zhao));if(skills&&air&&err>maxError&&err>.24f)Debug.Log("TACKLE GAP age="+(Time.time-first)+" error="+err+" body="+fb.rotation);maxError=Mathf.Max(maxError,err);float fx=Fx();if(fx>=0&&fx!=lastFx){activations++;lastFx=fx;if(first<0){first=Time.time;firstGain=(float)Field(fs,"balanceGain");firstMass=zb.mass;airborneActivation=!(bool)pt.GetField("isOnGround").GetValue(fan)||!(bool)pt.GetField("isOnGround").GetValue(zhao);Debug.Log("TACKLE ACTIVATION air="+air+" time="+first+" gain="+firstGain+" mass="+firstMass+" fanVy="+fb.velocity.y+" zhaoVy="+zb.velocity.y);}}
   if(first<0||Time.time-first<(air?.9f:.5f))maxTilt=Mathf.Max(maxTilt,Mathf.Abs(Mathf.DeltaAngle(0,fb.rotation)));
   if(!captured&&SystemInfo.graphicsDeviceType!=UnityEngine.Rendering.GraphicsDeviceType.Null&&skills&&air&&first>=0&&Time.time-first>.24f){captured=true;Capture();}
  }
  Debug.Log("TACKLE RUN skills="+skills+" air="+air+" rear="+rear+" activations="+activations+" tilt="+maxTilt+" joint="+maxError+" fanX="+fb.position.x+" zhaoX="+zb.position.x);
  Check(maxError<(skills?.3f:.45f),"connected skeleton survives impact and recovery skills="+skills+" air="+air);
  Check(fan.GetComponentsInChildren<Joint2D>().Length==9&&zhao.GetComponentsInChildren<Joint2D>().Length==9,"all native joints retained");
  if(!skills){Check(activations==0,"classic has no tackle skill");if(air)airBaseline=maxTilt;else groundBaseline=maxTilt;}
  else if(rear)Check(activations==0,"rear ball prevents tackle skill");
  else {Check(activations>0,"real automatic body contact triggers tackle air="+air);Check(firstMass>mass*1.5f,"Zhao braces during actual impact");Check(air?firstGain<=5.1f:firstGain<=8.1f,"impact temporarily softens Fan balance");if(air){airSpecial=maxTilt;Check(airborneActivation,"air boost occurs during real aerial contact");}else groundSpecial=maxTilt;Check(Mathf.Abs(zb.mass-mass)<.01f,"Zhao mass restored after brace");Check(!(bool)Field(fs,"weakenedBalance"),"Fan recovers normal balance gain");}
  FanAxis=ZhaoAxis=0;
 }
 void Capture(){Camera cam=Camera.main;RenderTexture previous=cam.targetTexture,active=RenderTexture.active;RenderTexture rt=new RenderTexture(1024,768,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;Texture2D png=new Texture2D(1024,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1024,768),0,0);png.Apply();System.IO.File.WriteAllBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../power-tackle-air.png")),png.EncodeToPNG());cam.targetTexture=previous;RenderTexture.active=active;rt.Release();Destroy(rt);Destroy(png);}
 IEnumerator AIContest(int mode){yield return Scene(true,mode);Move(fan,fb,new Vector2(-1.25f,2.2f));Move(zhao,zb,new Vector2(1.25f,2.2f));ball.position=new Vector2(0,40);fan.GetComponent<Animator>().SetTrigger("Jump");zhao.GetComponent<Animator>().SetTrigger("Jump");foreach(var b in fan.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(3,2);foreach(var b in zhao.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(-3,2);FanAxis=1;ZhaoAxis=-1;bool hit=false;float error=0;for(int i=0;i<100;i++){yield return new WaitForFixedUpdate();hit|=Fx()>=0;error=Mathf.Max(error,Mathf.Max(Joints(fan),Joints(zhao)));}Check(hit,"real contact skill works with original AI controller mode="+mode);Check(error<.3f,"AI body contest keeps all limbs connected mode="+mode+" error="+error);}
 IEnumerator Pause(){yield return Scene(true);Move(fan,fb,new Vector2(-.25f,fb.position.y));Move(zhao,zb,new Vector2(.25f,zb.position.y));ball.position=new Vector2(-5,40);FanAxis=1;ZhaoAxis=-1;float mass=zb.mass;for(int i=0;i<35&&Fx()<0;i++)yield return new WaitForFixedUpdate();Check(Fx()>=0,"pause test observes an actual impact");Time.timeScale=0;yield return null;yield return null;Check(Mathf.Abs(zb.mass-mass)<.01f&&!(bool)Field(fs,"weakenedBalance"),"pausing immediately restores brace mass and Fan muscle control");Check(Fx()<0,"pausing clears tackle animation");Time.timeScale=1;FanAxis=ZhaoAxis=0;}
 IEnumerator Guards(){yield return Scene(true);Move(fan,fb,new Vector2(-4,fb.position.y));Move(zhao,zb,new Vector2(1,zb.position.y));ball.position=new Vector2(0,-1.5f);for(int i=0;i<40;i++)yield return new WaitForFixedUpdate();Check(Fx()<0,"near ground ball alone cannot trigger old automatic interception");Check(typeof(PlayerSkills).GetMethod("AutoIntercept",P)==null&&typeof(PlayerSkills).GetMethod("ExtendKickPose",P)==null,"old long-reach kicking mechanic removed");Check(zhao.transform.Find("Body").GetComponent<PowerTackleContact>()!=null,"body contact relay attached");Check(zhao.transform.Find("L_LowLeg").GetComponent<PowerTackleContact>()==null,"leg taps are not body tackles");
  PlayerSkills.SetAction(zhao.GetComponent<Animator>(),"Kick",zhao);Check(Fx()<0,"ordinary shooting does not fake a body tackle animation");
 }
 IEnumerator Start(){Application.targetFrameRate=60;Application.runInBackground=true;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);yield return Contest(false,false);yield return Contest(true,false);yield return Contest(false,true);yield return Contest(true,true);yield return Contest(true,false,true);yield return Guards();Check(groundSpecial>groundBaseline+8,"ground tackle visibly disrupts balance versus classic baseline special="+groundSpecial+" baseline="+groundBaseline);Check(airSpecial>airBaseline+12,"air tackle visibly disrupts balance versus classic baseline special="+airSpecial+" baseline="+airBaseline);Check(PlayerSkills.TackleAirSpeed>PlayerSkills.TackleGroundSpeed&&PlayerSkills.TackleAirDuration>PlayerSkills.TackleGroundDuration,"air tackle is stronger and lasts longer");yield return AIContest(1);yield return AIContest(2);yield return Pause();PlayerSkills.ResetAll();Check((float)Field(fs,"staggerUntil")<0&&(float)Field(zs,"braceUntil")<0,"round reset clears impact states");Debug.Log("POWER TACKLE COMPLETE checks="+checks+" failures="+failures);Application.Quit();}
}
